    return tuple(sorted(cards))

def can_play(cards: List[int], stones: int) -> List[int]:
    '''Return all playable cards (<= stones)'''
    return [c for c in cards if c <= stones]

def remove_card(cards: List[int], card: int) -> List[int]:
    cards = cards.copy()
    cards.remove(card)
    return cards

def best_move(my_cards: List[int], opp_cards: List[int], stones: int, cache: Dict=None, depth: int=0, max_depth: int=25) -> (int, bool):
    """
    Returns (card_to_play, can_force_win)
