    # Memoization cache
    if cache is None:
        cache = {}
    key = (card_tuple(my_cards), card_tuple(opp_cards), stones)
    if key in cache:
        return cache[key]
    # Find all possible moves
    moves = can_play(my_cards, stones)
    if not moves:
        # Cannot play, immediate loss.
        cache[key] = (None, False)
        return (None, False)
    # Winning move available?
    for c in moves:
        if stones == c:
            # Take the rest, win
            cache[key] = (c, True)
            return (c, True)
    # Try all options for me
    for c in sorted(moves):
        n_my = remove_card(my_cards, c)
        n_stones = stones - c
        # Try all opponent's responses
