            cache[key] = (c, True)
            return (c, True)
        for oc in opp_moves:
            n_opp = remove_card(opp_cards, oc)
            n2_stones = n_stones - oc
            # Now it's my turn again
            _, i_can_win = best_move(n_my, n_opp, n2_stones, cache, depth+1, max_depth)
            # If there's any opp response where I cannot win, this move is not sure-win
            if not i_can_win:
                lose_here = False
                break
